  static int[] twoSum(int[] nums, int target) {
    // TODO
    return new int[] {-1, -1};
  }

  public static void main(String[] args) {
    int[] r = twoSum(new int[] {2, 7, 11, 15}, 9);
    System.out.println(r[0] + " " + r[1]);
  }
